head.script:

scwin.onpageload = function() {
	var data = [
	  "A","A","1",
	  "B","B","1",
	  "C","C","1",
	  "A-1","A-1","2",
	  "A-2","A-2","2",
	  "A-3","A-3","2",
	  "A-4","A-4","2",
	  "B-1","B-1","2",
	  "B-3","B-3","2",
	  "B-4","B-4","2",
	  "A-2-1","A-2-1","3"
	];
	dataList1.setData(data);
};

scwin.onpageunload = function() {

};

scwin.checkVal = function() {
	return WebSquare.wUnit.getDomById('selectbox1_itemTable').style.width == '400px';
}
scwin.unitTest = function() {
	//init
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('selectbox1').click()");
	WebSquare.wUnit.addCommand("pause", "400");		
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "400");
	//Run  and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest()
